CREATE TABLE Nurse (
    Nurse_ID INT PRIMARY KEY,
    Nurse_Name VARCHAR(100) NOT NULL,
    Gender VARCHAR(10),
    Phone_Number VARCHAR(15) UNIQUE,
    Department_ID INT,
    Shift VARCHAR(20),

    FOREIGN KEY (Department_ID) REFERENCES H_Department(Department_ID)
);
