CREATE TABLE Receptionist (
    Receptionist_ID INT PRIMARY KEY,
    Receptionist_Name VARCHAR(50) NOT NULL,
    Gender VARCHAR(10),
    Phone_No VARCHAR(15) UNIQUE,
    Shift VARCHAR(20)
);
