CREATE TABLE Prescription (
    Prescription_ID INT PRIMARY KEY,
    Appointment_ID INT,
    Doctor_ID INT,
    Medicine_Name VARCHAR(100),
    Dosage VARCHAR(50),
    Duration VARCHAR(50),
    Notes VARCHAR(255),

    FOREIGN KEY (Appointment_ID) REFERENCES h_appointment(Appointment_ID),
    FOREIGN KEY (Doctor_ID) REFERENCES h_doctor(Doctor_ID)
);
