--Display all records from the Patient table.
SELECT*FROM PATIENT;

--Display only patient names and ages.
SELECT patient_name,age FROM PATIENT;

--Display unique cities from the Patient table.
SELECT distinct address FROM PATIENT;

--Display patients whose age is greater than 40.
select * from patient 
where age>40;

--Display doctors whose specialization is 'Cardiology'.
select * from H_doctor 
where specialization = 'cardiology';

--Display patients whose age is between 20 and 40.
SELECT*FROM Patient 
WHERE AGE BETWEEN 20 AND 40;

--Display patients whose names start with 'A'.
select *from Patient 
where patient_name like'A%';
--Display patients ordered by age in descending order.
select * from patient
order by age desc;

--Display the first 10 patients.
select *from patient
limit 10;

--Count the total number of patients.
select count(*)as TOTAL_PATIENTS FROM patient;

--Find the maximum patient age.
SELECT MAX(AGE) AS MAXIMUM_AGE FROM PATIENT;

--Find the minimum patient age.
SELECT MIN(AGE) AS MINIMUM_AGE FROM PATIENT;

--Find the average patient age.
SELECT AVG(AGE) AS AVERAGE_AGE FROM PATIENT;

--Find the total billing amount.
SELECT SUM(TOTAL_AMOUNT)AS TOTAL_BILLING_AMOUNT FROM BILLING;

--Count the number of doctors.
SELECT COUNT(*) AS TOTAL_DOCTOR FROM H_DOCTOR
Count patients by gender.
SELECT GENDER,COUNT(*) AS PATIENTS FROM PATIENT
GROUP BY GENDER;

--Count doctors in each department.
SELECT DEPARTMENT_ID,COUNT(*) FROM H_DOCTOR
GROUP BY DEPARTMENT_ID;

--Find the total bill amount for each patient.
SELECT PATIENT_ID,SUM(TOTAL_AMOUNT)AS TOTAL_AMT FROM BILLING
GROUP BY PATIENT_ID;

--Display departments having more than 2 doctors.
SELECT DEPARTMENT_ID,COUNT(*)FROM H_DOCTOR
GROUP BY DEPARTMENT_ID
HAVING COUNT(*)>2;

--Display patients who visited more than twice.
SELECT PATIENT_ID,COUNT(*) AS TOTAL_VISIT
FROM H_APPOINTMENT
GROUP BY PATIENT_ID
HAVING COUNT(*)>2;

--Display doctor names in uppercase.
SELECT UPPER (DOCTOR_NAME)FROM H_DOCTOR;

--Display the length of each patient name.
SELECT PATIENT_NAME,LENGTH(PATIENT_NAME)FROM PATIENT;

--Concatenate patient name and city.
SELECT CONCAT(PATIENT_NAME,'  ',ADDRESS)FROM PATIENT;

--Display today date.
SELECT CURDATE();

--Display the current date and time.
SELECT NOW();

--Display doctor name and department name.
SELECT DR.DOCTOR_NAME,D.DEPARTMENT_NAME
FROM H_DOCTOR AS DR
JOIN H_DEPARTMENT AS D
ON DR.DEPARTMENT_ID =  D.DEPARTMENT_ID;

--Display patient name and doctor name.
SELECT p.Patient_name,
       d.Doctor_name
FROM H_Appointment a
INNER JOIN Patient p
ON a.Patient_id = p.Patient_id
INNER JOIN H_Doctor d
ON a.Doctor_id = d.Doctor_id;

--Display patient name and appointment date.
SELECT p.Patient_name, a.Appointment_date
FROM H_Appointment a
INNER JOIN Patient p
ON a.Patient_id = p.Patient_id;
--Display patient, doctor, and department.

select p.*,dr.*,d.*
from H_Appointment as a
join patient as p
on a.patient_id = p.patient_id
join H_doctor as dr
on a.doctor_id = dr.doctor_id
join H_department as d
on d.department_id = dr.department_id ;
 
 --Display billing with patient name.
 select patient_name,b.*
 from patient as p
 join billing as b
 on p.patient_id = b.patient_id;
 
--Display prescriptions with doctor name.
select dr.doctor_name,pr.*
from H_doctor as dr
join prescription as pr
on dr.doctor_id = pr.doctor_id; 
select*from Laboratory_Test;

--Display laboratory tests with patient names.
select p.patient_name,l.*
from patient as p
join Laboratory_Test as l
on p.patient_id = l.patient_id;

--Display admission details with room number.
select r.room_number,a.admission_id,a.admission_date
from room as r
join admission as a
on a.room_id = r.room_id;

--Find the oldest patient.
select *from patient 
where age=(select max(age) as oldest_patient from patient);

--Find the youngest patient.
select *from patient 
where age=(select min(age) as oldest_patient from patient);

--Find patients whose bill is above the average bill.
select * from billing  
where total_amount>(select avg(total_amount)from billing);

--Find doctors who have no appointments.
select * from H_doctor
where doctor_id not in (select doctor_id from H_appointment)
SELECT*FROM H_APPOINTMENT;

--Find the department with the highest number of doctors.
SELECT department_id,count(*)as total_doctor from H_doctor
group by department_id
order by total_doctor desc
limit 1;

--Update a patients phone number.

update patient
set phone_number = 9900887766
where patient_id=1
select * from patient;


--Add an Email column to the Patient table.
alter table patient
add email varchar(100)
--Modify the size of the Patient_name column.
alter table patient
modify patient_name varchar(100);

--Drop the Email column.
alter table patient
drop column email;

--Create a view showing patient and doctor details.
create view patient_doctor_details as
select p.patient_name,dr.doctor_name
from H_appointment as a
join patient as p
on a.patient_id=p.patient_id
join H_doctor as dr
on dr.doctor_id=a.doctor_id;
select * from patient_doctor_details;

--Create a stored procedure to display all doctors.
DELIMITER $$
create procedure doctor_details()
BEGIN
select*from H_doctor;
END$$
DELIMITER ;
CALL  doctor_details();

--Rank patients by billing amount using ROW_NUMBER().
SELECT
    Patient_id,
    Total_amount,
    ROW_NUMBER() OVER (ORDER BY Total_amount DESC) AS bill_rank
FROM Billing;